// main.ts
import { useContainer } from 'class-validator';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  // Направляем инстанцирование constraint class-validator через DI-контейнер Nest
  useContainer(app.select(AppModule), { fallbackOnErrors: true });
  app.useGlobalPipes(new ValidationPipe({ whitelist: true }));
  await app.listen(3000);
}
bootstrap();

Почему: по умолчанию class-validator делает `new IsEmailUniqueConstraint()` сам, вне Nest, так что UsersRepository из конструктора никогда не инжектится, и this.users undefined. useContainer(app.select(AppModule), ...) говорит class-validator резолвить constraint через контейнер Nest, так что @Injectable()-constraint получает свой repository. fallbackOnErrors: true обязателен, чтобы встроенные валидаторы (@IsEmail, @IsString, …), которые НЕ провайдеры Nest, откатывались на собственное инстанцирование class-validator вместо выброса 'provider not found'. Сам класс constraint менять не нужно — и он всё ещё должен быть зарегистрирован как провайдер, чтобы Nest мог его построить.
